def student(number, title, tasks):
    out = [f"# ИДЗ № {number}. {title}", "", "## Параметр варианта", "", "Используйте выданное преподавателем целое значение $v\in\{1,\ldots,10\}$. Во всех ответах сначала укажите модель и её условия, затем вычисления и интерпретацию.", ""]
    for index, (question, _, _, _) in enumerate(tasks, 1):
        out += [f"## Задача H{number:02d}-P{index:02d}", "", question, ""]
    out += ["## Требования к сдаче", "", "Сдать единый читаемый документ; сохранить точные выражения до округления; для вычислительного шага привести код или псевдокод и фиксированный seed; отдельно обозначить точный ответ, оценку и приближение.", ""]
    return "\n".join(out)


def teacher(number, title, tasks):
    out = [f"# ИДЗ № {number}. Закрытый ключ — {title}", "", "> Не публиковать: файл содержит решения, альтернативные методы и критерии.", ""]
    for index, (question, solution, alternative, mistake) in enumerate(tasks, 1):
        out += [f"## Задача H{number:02d}-P{index:02d}", "", question, "", "**Решение.**", "", f"1. Подставить параметр варианта $v$ и проверить область допустимых значений. 2. Назвать вероятностную модель и её предпосылки. 3. Выполнить вывод: {solution} 4. Проверить диапазон, размерность и предельный случай. 5. Интерпретировать ответ в терминах исходного сюжета.", "", f"**Альтернативный метод.** {alternative}", "", f"**Типичная ошибка.** {mistake}", ""]
    out += ["## Критерии оценивания", "", "Каждая задача — 4 балла: 1 балл за модель и предпосылки, 2 балла за корректный вывод и вычисления, 1 балл за проверку и интерпретацию. Арифметическая ошибка после правильной формулы снижает не более чем на 1 балл; отсутствие условий применимости не позволяет получить полный балл.", "", "## Источники разработки (не для публикации)", "", "- `sources/лекции.pdf` — обязательные тематические границы.", "- `sources/Gmurman_V_E_Teoria_veroyatnostey_i_matematicheskaya_statistika.pdf` и `sources/4816 методичка ТВМС.pdf` — определения и классические методы.", "- `sources/математика для машинного обучения.pdf` и `sources/Glubokoe_obuchenie_Pogruzhenie_v_mir_neyronnykh_setey.pdf` — интерпретации для ML и анализа данных.", "- Условия и числа трансформированы для курса; локальные источники не должны попадать в студенческую публикацию.", ""]
    return "\n".join(out)


for number, (title, tasks) in DATA.items():
    (ROOT / "homeworks" / f"{number:03d}_idz.md").write_text(student(number, title, tasks), encoding="utf-8")
    (ROOT / "lectures-teacher" / "homeworks" / f"{number:03d}_idz.md").write_text(teacher(number, title, tasks), encoding="utf-8")
